class Ingestion(BaseModel):
    """
    One submission, whatever the item count — the receipt for a single request, and the only handle to keep. A receipt whose `staged` counts are all zero created no work, and `intake` says which of the two reasons it was: entries reading `ignored` mean nothing in the payload could be used, anything else means the content was already stored by an earlier submission — in which case `status` covers the work holding it, and can be `failed`.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    ingestion_id: str = Field(
        ..., alias="ingestionId", description="Stable unique identifier for this submission."
    )
    source: Literal[
        "fhir/r4", "fhir/r5", "cda/r2", "session/v1", "batch/legacy", "document/legacy"
    ] = Field(
        ...,
        description="Version-qualified entry family. `batch/legacy` and `document/legacy` are historical only — no current route writes them.",
    )
    mime_type: str = Field(..., alias="mimeType", description="Media type as received.")
    received_at: str = Field(
        ..., alias="receivedAt", description="ISO 8601 timestamp when the submission was accepted."
    )
    status: Literal["pending", "processing", "succeeded", "partial", "failed"] = Field(
        ..., description="Where this submission stands, across all its work."
    )
    staged: IngestionStaged
    intake: list[IngestionIntakeItem] | None = Field(
        None, description="What the submission held. Absent when it was not recorded."
    )
    started_at: str | None = Field(
        ...,
        alias="startedAt",
        description="ISO 8601 timestamp when work on this submission was first picked up. Null while it is still queued, and on a submission that started no work.",
    )
    completed_at: str | None = Field(
        ...,
        alias="completedAt",
        description="ISO 8601 timestamp when all of this submission's work settled. Null until then.",
    )
    failure: Failure | None = Field(
        ...,
        description="Why this submission did not land. Null unless `status` is `failed` or `partial`.",
    )


